const EnterpriseEvaluationReport_Operation = `
query EnterpriseEvaluationReport ($input: EvaluationReportInput!) {
	evaluationReport(input: $input) {
		meshID
		rubricID
		startTime
		endTime
		interval
		metrics {
			rubricMetricID
			type
			name
			category
			unit
			aggregation
			weight
		}
		versions {
			meshVersionID
			ordinal
			label
			summary {
				... EnterpriseReportAggregate
			}
			points {
				startTime
				endTime
				aggregate {
					... EnterpriseReportAggregate
				}
			}
		}
	}
}
fragment EnterpriseReportAggregate on EvaluationReportAggregate {
	totalRequestCount
	selectedRequestCount
	successfulRequestCount
	latestPendingRequestCount
	latestFailedRequestCount
	coverageRatio
	rubricScore
	metrics {
		rubricMetricID
		value
		score
		contributingRequestCount
	}
}
`

